'use client'

import { useAfterEffectsSettle, useCurrentUser } from '@/util/hooks'
import React from 'react'

export default function MembershipCardFront() {
    const defaultNameFontSize = '56'
    const [nameFontSize, setNameFontSize] = React.useState(defaultNameFontSize)

    const defaultDiscordHandleFontSize = '40'
    const [discordHandleFontSize, setDiscordHandleFontSize] = React.useState(
        defaultDiscordHandleFontSize
    )
    const [discordLogoX, setDiscordLogoX] = React.useState(506.25)
    const discordHandleRef = React.useRef<SVGTextElement>(null)

    const loggedInUser = useCurrentUser()

    const discordUsername =
        loggedInUser?.data?.discordUsers?.[0]?.username ?? 'discord.handle'
    const firstName = loggedInUser?.data?.firstName ?? 'Firstname'
    const lastName = loggedInUser?.data?.lastName ?? 'Lastname'

    const issueDate = new Date()
    const name = `${firstName} ${lastName}`

    /**
     * Resizes text dynamically based on length to prevent overflow
     */
    const rescaleTextElement = (
        querySelector: string,
        setState: (newState: string) => void,
        override?: string
    ): void => {
        const textEl: SVGTextContentElement =
            document.querySelector(querySelector)!
        const textParentEl = document.querySelector(
            `${querySelector}-container`
        )
        if (!textEl || !textParentEl) return // probs unnecessary

        const currentFontSize = textEl.getAttribute('font-size')
        if (!currentFontSize) return

        const newFontSize = override
            ? parseFloat(override)
            : parseFloat(currentFontSize) - 2 // this feels gentle enough as a scale factor
        if (newFontSize === 0) return

        textEl.setAttribute('font-size', `${newFontSize}`)

        const newTextWidth = textEl.getComputedTextLength()
        const maxTextWidth = parseFloat(
            textParentEl.getAttribute('width') ?? '843'
        ) // sensible default of 80% of card width
        if (newTextWidth >= maxTextWidth) {
            setState(`${newFontSize}`) // update state to trigger memo
        }
    }
    React.useEffect(
        () => rescaleTextElement('#membership-card-user-name', setNameFontSize),
        [nameFontSize]
    ) // rescale on component mount
    // reset behavior if user changes their name
    React.useLayoutEffect(
        () =>
            rescaleTextElement(
                '#membership-card-user-name',
                setNameFontSize,
                defaultNameFontSize
            ),
        [name]
    )

    /**
     * Resizes Discord handle text and adjusts positioning
     * of the Discord logo based on length to prevent overflown
     */
    const rescaleDiscordHandle = (): void => {
        const textEl = discordHandleRef.current
        if (!textEl) return

        const logoWidth = 56
        const gap = 10
        const textBounds = textEl.getBBox()
        const logoX = textBounds.x - gap - logoWidth

        if (Number.isFinite(logoX)) {
            setDiscordLogoX((prev) =>
                Math.abs(prev - logoX) > 0.25 ? logoX : prev
            )
        }
    }
    React.useEffect(
        () =>
            rescaleTextElement(
                '#membership-card-discord-handle',
                setDiscordHandleFontSize
            ),
        [discordHandleFontSize]
    )
    // reset, same as above
    React.useLayoutEffect(
        () =>
            rescaleTextElement(
                '#membership-card-discord-handle',
                setDiscordHandleFontSize,
                defaultDiscordHandleFontSize
            ),
        [discordUsername]
    )

    // debounce the discord handle resize so it fires after the useEffect loop
    useAfterEffectsSettle(rescaleDiscordHandle, [
        discordUsername,
        discordHandleFontSize,
    ])

    return (
        <svg
            width="100%"
            height="100%"
            viewBox="0 4 242 145"
            style={{
                fillRule: 'evenodd',
                clipRule: 'evenodd',
                strokeLinejoin: 'round',
                strokeMiterlimit: '2',
            }}
            xmlnsXlink="http://www.w3.org/1999/xlink"
        >
            <g id="Artboard1" transform="matrix(0.24,0,0,0.24,0,0)">
                <rect
                    x="0"
                    y="0"
                    width="1012.5"
                    height="637.5"
                    style={{ fill: 'none' }}
                />
                <clipPath id="_clip1">
                    <rect x="0" y="0" width="1012.5" height="637.5" />
                </clipPath>
                <g clipPath="url(#_clip1)">
                    <g
                        id="Halftonethingyfeawew"
                        transform="matrix(0.801853,0,0,0.801853,-56.25,-94.5919)"
                    >
                        <g transform="matrix(5.1963,-0,-0,5.1963,70.15,117.967)">
                            <use
                                xlinkHref="#_Image2"
                                x="0"
                                y="0"
                                width="243px"
                                height="153px"
                            />
                        </g>
                    </g>
                    {/* dynamic part */}
                    <text
                        x="506.25"
                        y="300.625"
                        fontFamily="'Montserrat-SemiBold', 'Montserrat'"
                        fontSize="32"
                        fontWeight="700"
                        fill="#cc3333"
                        textAnchor="middle"
                        letterSpacing="0.5"
                    >
                        Member Since: {issueDate.getFullYear()}
                    </text>
                    <g
                        id="membership-card-user-name-container"
                        width="843"
                        height="125"
                    >
                        <text
                            id="membership-card-user-name"
                            x="506.25"
                            y="423.25"
                            fontFamily="'Montserrat-SemiBold', 'Montserrat'"
                            fontWeight="700"
                            fontSize={defaultNameFontSize}
                            fill="white"
                            textAnchor="middle"
                            letterSpacing="1"
                        >
                            {name}
                        </text>
                    </g>

                    <svg
                        id="membership-card-discord-logo"
                        width="56"
                        height="56"
                        viewBox="0 0 256 256"
                        preserveAspectRatio="xMidYMid"
                        x={discordLogoX}
                        y={458.125}
                    >
                        <path
                            d="M216.856339,16.5966031 C200.285002,8.84328665 182.566144,3.2084988 164.041564,0 C161.766523,4.11318106 159.108624,9.64549908 157.276099,14.0464379 C137.583995,11.0849896 118.072967,11.0849896 98.7430163,14.0464379 C96.9108417,9.64549908 94.1925838,4.11318106 91.8971895,0 C73.3526068,3.2084988 55.6133949,8.86399117 39.0420583,16.6376612 C5.61752293,67.146514 -3.4433191,116.400813 1.08711069,164.955721 C23.2560196,181.510915 44.7403634,191.567697 65.8621325,198.148576 C71.0772151,190.971126 75.7283628,183.341335 79.7352139,175.300261 C72.104019,172.400575 64.7949724,168.822202 57.8887866,164.667963 C59.7209612,163.310589 61.5131304,161.891452 63.2445898,160.431257 C105.36741,180.133187 151.134928,180.133187 192.754523,160.431257 C194.506336,161.891452 196.298154,163.310589 198.110326,164.667963 C191.183787,168.842556 183.854737,172.420929 176.223542,175.320965 C180.230393,183.341335 184.861538,190.991831 190.096624,198.16893 C211.238746,191.588051 232.743023,181.531619 254.911949,164.955721 C260.227747,108.668201 245.831087,59.8662432 216.856339,16.5966031 Z M85.4738752,135.09489 C72.8290281,135.09489 62.4592217,123.290155 62.4592217,108.914901 C62.4592217,94.5396472 72.607595,82.7145587 85.4738752,82.7145587 C98.3405064,82.7145587 108.709962,94.5189427 108.488529,108.914901 C108.508531,123.290155 98.3405064,135.09489 85.4738752,135.09489 Z M170.525237,135.09489 C157.88039,135.09489 147.510584,123.290155 147.510584,108.914901 C147.510584,94.5396472 157.658606,82.7145587 170.525237,82.7145587 C183.391518,82.7145587 193.761324,94.5189427 193.539891,108.914901 C193.539891,123.290155 183.391518,135.09489 170.525237,135.09489 Z"
                            fill="white"
                            fillRule="nonzero"
                        />
                    </svg>

                    <g
                        id="membership-card-discord-handle-container"
                        width="790"
                    >
                        <text
                            id="membership-card-discord-handle"
                            ref={discordHandleRef}
                            x={506.25 + 56}
                            y="492"
                            fontFamily="'Montserrat-SemiBold', 'Montserrat'"
                            fontWeight="700"
                            fontSize={defaultDiscordHandleFontSize}
                            fill="white"
                            letterSpacing="0.5"
                            textAnchor="middle"
                        >
                            {discordUsername}
                        </text>
                    </g>
                </g>
            </g>
            <defs>
                <image
                    id="_Image2"
                    width="243px"
                    height="153px"
                    xlinkHref="data:image/png;base64,"
                />
            </defs>
        </svg>
    )
}
